<?php
require dirname(__DIR__).'/vendor/autoload.php';
$app=require dirname(__DIR__).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();

use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use App\Support\TextEncoding;
$tables=['reports'=>['title','keyword','description','meta_title','meta_description','meta_keywords','region','key_info'],'reports_meta'=>['content','toc','tables_figures'],'news'=>['headline','content','meta_title','meta_description','meta_keywords'],'categories'=>['name','description','meta_title','meta_description','meta_keywords'],'publishers'=>['name','description'],'lr_pages'=>['title','content'],'lr_report_faqs'=>['faqs'],'country'=>['name','nicename']];
$stats=[];$allPairs=[];$apply=in_array('--apply',$argv,true);$conflicts=0;
foreach($tables as $table=>$wanted){if(!Schema::hasTable($table))continue;$columns=array_intersect($wanted,Schema::getColumnListing($table));if(!$columns)continue;$pk=$table==='lr_report_faqs'?'report_id':'id';$count=0;$fields=[];$unknown=0;$examples=[];
 $query=DB::table($table)->select(array_merge([$pk],array_values($columns)))->where(function($q)use($columns){foreach($columns as $field)$q->orWhereRaw('CONVERT(`'.$field.'` USING utf8mb4) COLLATE utf8mb4_bin REGEXP ?', ["[\u{00c2}-\u{00f4}\u{fffd}]|&(acirc|Atilde|Acirc|iuml|#226|#195|#194|#65533|#x[fF]{3}[dD]|#x[eE]2|#x[cC]3|#x[cC]2);|\\\\u00[c-fC-F][0-9a-fA-F]|\\\\ufffd"]);});
 $query->chunkById(200,function($rows)use($table,$columns,$pk,&$count,&$fields,&$unknown,&$examples,&$allPairs,$apply,&$conflicts){foreach($rows as $row){$updates=[];foreach($columns as $field){$old=$row->$field;if(!is_string($old))continue;$pairs=[];$new=in_array($field,['key_info','faqs'],true)?TextEncoding::json($old,$pairs):TextEncoding::repair($old,$pairs);$probe=$new;if(in_array($field,['key_info','faqs'],true)){$decoded=json_decode($new,true);if(is_array($decoded))$probe=json_encode($decoded,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}$probe=html_entity_decode($probe,ENT_QUOTES|ENT_HTML5,'UTF-8');if(str_contains($probe,"\u{fffd}")){$unknown++;preg_match_all('/.{0,55}\x{FFFD}.{0,85}/u',$probe,$missing);foreach($missing[0] as $excerpt)if(count($examples)<100)$examples[]=['id'=>$row->$pk,'field'=>$field,'excerpt'=>$excerpt];}if($old===$new)continue;$updates[$field]=$new;$fields[$field]=($fields[$field]??0)+1;foreach($pairs as $from=>$to)$allPairs[$table][$field][$from]=$to;}if(!$updates)continue;$count++;if($count%5000===0){echo $table.': scanned '.$count.' repairable rows'.PHP_EOL;flush();}if($apply){DB::transaction(function()use($table,$pk,$row,$updates,&$conflicts){$current=DB::table($table)->where($pk,$row->$pk)->lockForUpdate()->first(array_keys($updates));foreach($updates as $field=>$value)if(!$current||$current->$field!==$row->$field){$conflicts++;return;}DB::table($table)->where($pk,$row->$pk)->update($updates);});}}},$pk);
 $stats[$table]=['repairable_rows'=>$count,'fields'=>$fields,'unresolved_fields'=>$unknown,'examples'=>$examples];echo $table.': '.$count.' repairable rows, '.$unknown.' fields with unrecoverable replacement characters'.PHP_EOL;flush();
}
$result=['apply'=>$apply,'tables'=>$stats,'conflicts'=>$conflicts,'replacements'=>$allPairs];file_put_contents(storage_path('app/private/text-encoding-'.($apply?'applied':'audit').'.json'),json_encode($result,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo '__RESULT__'.json_encode($result,JSON_THROW_ON_ERROR).PHP_EOL;
